import{_ as a,o as t,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"信号源","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/signal_source/index.md","filePath":"v0.3.0-alpha/modules/signal_source/index.md"}'),r={name:"v0.3.0-alpha/modules/signal_source/index.md"};function l(i,e,c,n,h,s){return t(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="信号源" tabindex="-1">信号源 <a class="header-anchor" href="#信号源" aria-label="Permalink to &quot;信号源&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>signal_source</code> · 模块定义版本：6</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>按采样时钟生成规则的实数波形，可用作测试输入、载波或直流参考。正弦波的周期由频率决定，幅度决定纵向大小，直流偏置整体移动波形。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>信号源.out → 增益器.in → 观察器</code>。也可将同一个输出分支接到加法器和滤波器，比较处理前后的信号。<code>cmd</code> 是消息输入，不能把数值流接到这个口。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>cmd</code>（cmd（消息））</td><td><code>message</code></td><td>消息；不计入流路数</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>先用采样率确定时间刻度，再选择信号频率。<code>frequency_hz</code> 须满足半开范围 <code>[-Fs/2, Fs/2)</code>，其中 <code>Fs</code> 为 <code>sample_rate_hz</code>：包含负边界，不含正边界。每周期样本越少，时域折线越难表现原来的连续形状。</p><p>幅度与偏置分别影响波形大小和中心位置。方波、三角波、锯齿波沿用单极性定义，先缩放再加偏置，不能把它们都按正负对称的正弦波理解；初相使用弧度。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>采样率 (Hz)<br><code>sample_rate_hz</code></td><td><code>4096</code></td><td>范围 1 至 1000000；Master 支持 1–1000000 Hz，可输入小数；下限保证单个采样周期不超过 1 秒。</td><td>重新准备</td></tr><tr><td>频率 (Hz)<br><code>frequency_hz</code></td><td><code>64</code></td><td>范围 -500000 至 500000；必须小于采样率的一半；严格小于 <code>sample_rate_hz</code> × 0.5；还须满足本节关联约束</td><td>可在线应用</td></tr><tr><td>幅度<br><code>amplitude</code></td><td><code>1</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>波形<br><code>waveform</code></td><td><code>sine</code></td><td>正弦 (<code>sine</code>)；余弦 (<code>cosine</code>)；方波 (<code>square</code>)；三角波 (<code>triangle</code>)；锯齿波 (<code>sawtooth</code>)；常量 (<code>constant</code>)；方波、三角波和锯齿波沿用 GNU Radio 单极性波形；先乘幅度再加偏置。</td><td>可在线应用</td></tr><tr><td>初相 (rad)<br><code>phase_rad</code></td><td><code>0</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>直流偏置<br><code>offset</code></td><td><code>0</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>frequency_hz</code></li><li><code>amplitude</code></li><li><code>waveform</code></li><li><code>phase_rad</code></li><li><code>offset</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>在线操作针对正在运行的节点，普通编辑先保存在工程草稿。改变采样时钟需要重新准备。<code>cmd</code> 接受频率、幅度、相位或偏置的消息字典；消息入队与观察到输出改变分别判断，消息不作为保存工程后的自动重放步骤。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="实数信号、分支运算与三种选频滤波" tabindex="-1">实数信号、分支运算与三种选频滤波 <a class="header-anchor" href="#实数信号、分支运算与三种选频滤波" aria-label="Permalink to &quot;实数信号、分支运算与三种选频滤波&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/real-processing.cnsproj" download>下载 real-processing.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>实数信号、分支运算与三种选频滤波</p><ul><li>64 Hz 与 768 Hz 混合信号分支进入低通、高通、带通；比较增益、相乘、8 点延时与两抽头 FIR。</li></ul><h3 id="原生消息输入与实际输出" tabindex="-1">原生消息输入与实际输出 <a class="header-anchor" href="#原生消息输入与实际输出" aria-label="Permalink to &quot;原生消息输入与实际输出&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/message-control.cnsproj" download>下载 message-control.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>原生消息输入与实际输出</p><ul><li>普通打开仅运行保存的静态构造图：常量 1、点表与零延时，不自动投递消息。开发验证通过真实运行接口向 dly 投递整数 2、向 cmd 投递 {&quot;ampl&quot;:3,&quot;offset&quot;:2}，核对常量变为 5 及点表延时 2 item。当前属性页尚无消息投递表单。</li></ul><p>当前属性页未提供消息投递表单。运行消息由配套开发验证脚本投递，并在短连续运行中观察实际变化；普通 F5 只运行保存的静态构造图，重开工程不会重放消息。</p><h3 id="_512-点周期-hamming-与-75-重叠频谱" tabindex="-1">512 点周期 Hamming 与 75% 重叠频谱 <a class="header-anchor" href="#_512-点周期-hamming-与-75-重叠频谱" aria-label="Permalink to &quot;512 点周期 Hamming 与 75% 重叠频谱&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/spectrum-configuration.cnsproj" download>下载 spectrum-configuration.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>512 点周期 Hamming 与 75% 重叠频谱</p><ul><li>两路同为 4096 item/s，FFT 长度 512，周期 Hamming，重叠 75%（步长 128）。有限 2048 item 各产生 13 帧；实数单边谱在 256 Hz 峰值 1.25，复数双边谱在 -512 Hz 峰值 0.625。</li></ul><h3 id="调频、幅相、正交解调与二值-bpsk-映射" tabindex="-1">调频、幅相、正交解调与二值 BPSK 映射 <a class="header-anchor" href="#调频、幅相、正交解调与二值-bpsk-映射" aria-label="Permalink to &quot;调频、幅相、正交解调与二值 BPSK 映射&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/modulation-chain.cnsproj" download>下载 modulation-chain.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>调频、幅相、正交解调与二值 BPSK 映射</p><ul><li>Fs=4096，常量 1 经 sensitivity=π/8 调频得到 +256 Hz、模长 1 的复相量，首项先累加。幅相输出主值相位；gain=8/π 解调首项为 0、后续约 1。二值判决对零和正值均输出索引 1，按生产 BPSK 点表映射。码元 OUT 固定 M2，不生成模拟幅度频谱。</li></ul><p>在实数处理示例中，观察信号源 1 的 64 Hz 波形与信号源 2 的 768 Hz 波形，再查看加法器输出中的两个频率分量。全部来自本机生成。</p><p>消息示例由配套开发验证脚本在运行后向常量源投递 <code>{&quot;ampl&quot;:3,&quot;offset&quot;:2}</code>，检查后续输出变为 5。当前属性页未提供消息投递表单；打开下载工程并按 F5 只运行其中的初始图，不会自动发送或恢复这些消息。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>频率改了，曲线却没有改变？</strong> 检查修改的是哪个信号源，运行中是否执行“在线应用”，以及观察器是否绑定该节点输出。</p><p><strong>频谱出现直流分量？</strong> 先检查偏置和所选波形的平均值，再判断是否属于需要滤除的成分。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/01-link-overview/">01 状态回传的链路全貌</a></li><li><a href="./../../learn/02-wave-quantities/">02 幅度、频率与相位</a></li><li><a href="./../../learn/03-sampling/">03 采样点与波形外观</a></li><li><a href="./../../learn/04-signal-views/">04 时域、频谱与瀑布</a></li><li><a href="./../../learn/05-noise/">05 信号混入噪声</a></li><li><a href="./../../learn/06-filter/">06 滤波保留了什么</a></li><li><a href="./../../learn/08-fm/">08 从数值到调频再解调</a></li></ul>',47)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
